"use strict";(self.webpackChunkstarmade_guides=self.webpackChunkstarmade_guides||[]).push([[6332],{1025(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"defaultSidebar":[{"type":"category","label":"Getting Started","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/getting-started/introduction","label":"Introduction to StarMade","docId":"getting-started/introduction","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/getting-started/hud-and-interface","label":"HUD & Interface","docId":"getting-started/hud-and-interface","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/getting-started/basic-controls","label":"Basic Controls","docId":"getting-started/basic-controls","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/getting-started/character-movement","label":"Character Movement","docId":"getting-started/character-movement","unlisted":false}]},{"type":"category","label":"Building","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/building/advanced-building","label":"Advanced Building","docId":"building/advanced-building","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/building/power-basics","label":"Power Basics","docId":"building/power-basics","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/building/docking-and-turrets","label":"Docking & Turrets","docId":"building/docking-and-turrets","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/building/shipyards","label":"Shipyards","docId":"building/shipyards","unlisted":false}]},{"type":"category","label":"Ships","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/ships/ship-basics","label":"Ship Basics","docId":"ships/ship-basics","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/building-a-ship","label":"Building a Ship","docId":"ships/building-a-ship","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/ship-systems","label":"Ship Systems","docId":"ships/ship-systems","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/reactors","label":"Reactors and Stabilizers","docId":"ships/reactors","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/chambers","label":"Reactor Chambers","docId":"ships/chambers","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/thrusters","label":"Thrusters","docId":"ships/thrusters","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/shields","label":"Shields","docId":"ships/shields","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/weapons-and-effects","label":"Weapons","docId":"ships/weapons-and-effects","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/salvagers","label":"Salvagers","docId":"ships/salvagers","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/armor-and-damage","label":"Armor & Damage","docId":"ships/armor-and-damage","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ships/ship-ai","label":"Ship & Turret AI","docId":"ships/ship-ai","unlisted":false}]},{"type":"category","label":"World","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/world/navigation","label":"Navigation","docId":"world/navigation","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/world/resources-and-mining","label":"Resources & Mining","docId":"world/resources-and-mining","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/world/asteroids","label":"Asteroids","docId":"world/asteroids","unlisted":false}]},{"type":"category","label":"Manufacturing","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/manufacturing/crafting-basics","label":"Crafting Basics","docId":"manufacturing/crafting-basics","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/manufacturing/factories","label":"Factories & Production","docId":"manufacturing/factories","unlisted":false}]},{"type":"category","label":"AI & Fleets","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/ai-and-fleets/ai-systems","label":"AI Systems","docId":"ai-and-fleets/ai-systems","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/ai-and-fleets/fleets","label":"Fleets","docId":"ai-and-fleets/fleets","unlisted":false}]},{"type":"category","label":"Logic","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/logic/logic-basics","label":"Logic: Basics","docId":"logic/logic-basics","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/logic/logic-gates","label":"Logic: Gates","docId":"logic/logic-gates","unlisted":false}]},{"type":"category","label":"Multiplayer","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/StarMade-Guides/pre/multiplayer/factions","label":"Factions","docId":"multiplayer/factions","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/multiplayer/catalog-and-blueprints","label":"Catalog & Blueprints","docId":"multiplayer/catalog-and-blueprints","unlisted":false}]},{"type":"link","href":"/StarMade-Guides/pre/","label":"StarMade Guides","docId":"index","unlisted":false},{"type":"link","href":"/StarMade-Guides/pre/starmade-galaxy","label":"StarMade Galaxy","docId":"starmade-galaxy","unlisted":false}]},"docs":{"ai-and-fleets/ai-systems":{"id":"ai-and-fleets/ai-systems","title":"AI Systems","description":"StarMade has two distinct AI systems: ship/turret AI controlled by the AI Module block, and AI Crew \u2014 NPC companions you can hire and command.","sidebar":"defaultSidebar"},"ai-and-fleets/fleets":{"id":"ai-and-fleets/fleets","title":"Fleets","description":"A fleet is a group of AI-controlled ships that act together under a single set of orders. No special block is required \u2014 fleets are created and managed entirely through the Fleet Panel (K).","sidebar":"defaultSidebar"},"building/advanced-building":{"id":"building/advanced-building","title":"Advanced Building","description":"Build mode has a radial menu of shape tools for placing blocks in geometric patterns, and an advanced build mode panel full of power tools. Together they dramatically speed up construction of large ships and stations.","sidebar":"defaultSidebar"},"building/docking-and-turrets":{"id":"building/docking-and-turrets","title":"Docking & Turrets","description":"StarMade uses a rail-based docking system. A ship docks to rail blocks on a station or another ship with a Rail Docker block. Rails handle fixed docking, turrets, moving platforms and elevators, cargo transfer, and automatic hangar docking.","sidebar":"defaultSidebar"},"building/power-basics":{"id":"building/power-basics","title":"Power Basics","description":"A ship core makes no power of its own. Without a reactor your thrusters run at only 5% of their strength and weapons, shields and other systems don\'t work, so every real ship needs a reactor.","sidebar":"defaultSidebar"},"building/shipyards":{"id":"building/shipyards","title":"Shipyards","description":"Shipyards are Space Station based systems that allow players to design ships in a temporary virtual creative environment and mass produce those designs from a loaded design, which is similar to a blueprint. You can also dock an existing ship into a shipyard to completely deconstruct it, or repair it using an existing loaded design.","sidebar":"defaultSidebar"},"getting-started/basic-controls":{"id":"getting-started/basic-controls","title":"Basic Controls","description":"All key bindings can be remapped in the game settings. The defaults listed here are the standard layout. Panel keys (inventory, map, catalog and so on) are listed in HUD & Interface.","sidebar":"defaultSidebar"},"getting-started/character-movement":{"id":"getting-started/character-movement","title":"Character Movement","description":"Your character moves in two very different ways: walking where there is gravity, and floating freely in zero gravity.","sidebar":"defaultSidebar"},"getting-started/hud-and-interface":{"id":"getting-started/hud-and-interface","title":"HUD & Interface","description":"The HUD (Heads-Up Display) gives you live information about your character and ship at a glance.","sidebar":"defaultSidebar"},"getting-started/introduction":{"id":"getting-started/introduction","title":"Introduction to StarMade","description":"StarMade is a voxel-based space sandbox game. You explore a procedurally generated universe, build ships and stations block by block, gather resources, craft items, fight enemies, and team up with other players.","sidebar":"defaultSidebar"},"index":{"id":"index","title":"StarMade Guides","description":"Welcome to the StarMade Guides! This is a replica of the in-game documentation built by the community to help players get started in StarMade. The old documentation can be found here, but is not maintained. For the most up to date information please refer to this site or to the in-game guides. Click on the Introduction to get started.","sidebar":"defaultSidebar"},"logic/logic-basics":{"id":"logic/logic-basics","title":"Logic: Basics","description":"StarMade has a fully integrated, Turing-complete logic system. You can build anything from a simple light switch to a fully functional CPU using logic blocks connected to each other.","sidebar":"defaultSidebar"},"logic/logic-gates":{"id":"logic/logic-gates","title":"Logic: Gates","description":"Building on the basics of activation blocks and connections, StarMade provides four additional logic blocks that let you build complex circuits.","sidebar":"defaultSidebar"},"manufacturing/crafting-basics":{"id":"manufacturing/crafting-basics","title":"Crafting Basics","description":"StarMade\'s crafting system is divided into three basic stages: refining, component manufacturing, and block assembly.","sidebar":"defaultSidebar"},"manufacturing/factories":{"id":"manufacturing/factories","title":"Factories & Production","description":"Production or \'crafting\' in StarMade is primarily achieved via various types of Factories. A full production line requires multiple linked factories.","sidebar":"defaultSidebar"},"multiplayer/catalog-and-blueprints":{"id":"multiplayer/catalog-and-blueprints","title":"Catalog & Blueprints","description":"The Catalog stores ship blueprints \u2014 saved snapshots of ships and stations that can be purchased and spawned elsewhere.","sidebar":"defaultSidebar"},"multiplayer/factions":{"id":"multiplayer/factions","title":"Factions","description":"Factions let players group together, protect their ships and stations, declare wars, and organise with ranks and permissions.","sidebar":"defaultSidebar"},"ships/armor-and-damage":{"id":"ships/armor-and-damage","title":"Armor & Damage","description":"Understanding armor and damage types is essential for both building durable ships and designing effective weapons.","sidebar":"defaultSidebar"},"ships/building-a-ship":{"id":"ships/building-a-ship","title":"Building a Ship","description":"Ships are built block by block in Build Mode. This guide takes you through spawning your first ship and making it flight-ready.","sidebar":"defaultSidebar"},"ships/chambers":{"id":"ships/chambers","title":"Reactor Chambers","description":"Chambers are special blocks that plug into your reactor to give your ship additional capabilities \u2014 jump drives, stealth, enhanced mobility, and more. They are the primary way to unlock advanced ship systems.","sidebar":"defaultSidebar"},"ships/reactors":{"id":"ships/reactors","title":"Reactors and Stabilizers","description":"Every ship needs a power reactor to run its systems. This guide covers how to build and balance your reactor.","sidebar":"defaultSidebar"},"ships/salvagers":{"id":"ships/salvagers","title":"Salvagers","description":"Salvagers function similarly to weapons, but without secondaries or effects. Salvage systems are used to mine ores from asteroids, and to salvage overheating shipwrecks and abandoned stations.","sidebar":"defaultSidebar"},"ships/shields":{"id":"ships/shields","title":"Shields","description":"Shields are your ship\'s first layer of defence. All incoming damage hits shields before reaching your hull and blocks. When shields are depleted they enter a Shield Outage before recharging.","sidebar":"defaultSidebar"},"ships/ship-ai":{"id":"ships/ship-ai","title":"Ship & Turret AI","description":"A ship, station turret or docked entity with a BOBBY AI Module can fly and fight on its own. Only one AI Module is allowed per ship.","sidebar":"defaultSidebar"},"ships/ship-basics":{"id":"ships/ship-basics","title":"Ship Basics","description":"A ship is the primary way to travel through space, fight enemies, and carry cargo. Every ship is built around a Ship Core block \u2014 the single block that defines the ship.","sidebar":"defaultSidebar"},"ships/ship-systems":{"id":"ships/ship-systems","title":"Ship Systems","description":"StarMade uses a block-group system to determine how sets of same-type blocks behave together. This is most important for weapons, where grouping affects how shots are fired.","sidebar":"defaultSidebar"},"ships/thrusters":{"id":"ships/thrusters","title":"Thrusters","description":"Thrusters are modules that allow you to move your ship, and consume energy from your Reactor in order to do so. Thrusters have a linear power consumption per module, but diminishing returns on how much thrust each thruster module on a ship produces. Larger ships will require more thrusters and more power to move at the same speed as a smaller ship.","sidebar":"defaultSidebar"},"ships/weapons-and-effects":{"id":"ships/weapons-and-effects","title":"Weapons","description":"StarMade has three primary weapon types, three utility weapons, and explosive warhead blocks. Primary weapons can be linked to a secondary weapon to alter the functions and stats of the primary weapon, and can be linked to an effect system to alter its damage type distribution.","sidebar":"defaultSidebar"},"starmade-galaxy":{"id":"starmade-galaxy","title":"StarMade Galaxy","description":"StarMade Galaxy is a new version of StarMade built in Unity SRP that one of the developers of the original game is working on in their free time. This version of the game is publicly unavailable as of the time of writing, however you can support Schema via Patreon to gain access to the experimental branch of StarMade Galaxy, but there is currently no build yet. Note that this is completely optional, and that the official Java version is still maintained and widely used throughout the community. If you\'re new to StarMade the suggestion remains to stick to the Java version from Steam or the official StarMade site. There is a teaser trailer of StarMade Galaxy available on YouTube.","sidebar":"defaultSidebar"},"world/asteroids":{"id":"world/asteroids","title":"Asteroids","description":"asteroidsfig1.jpg","sidebar":"defaultSidebar"},"world/navigation":{"id":"world/navigation","title":"Navigation","description":"The StarMade universe is vast. Understanding its structure and using the navigation tools efficiently will save you a lot of time.","sidebar":"defaultSidebar"},"world/resources-and-mining":{"id":"world/resources-and-mining","title":"Resources & Mining","description":"Raw resources are the foundation of everything you build. There are four families of raw materials, each found in different places across the universe.","sidebar":"defaultSidebar"}}}}')}}]);